<?php
declare(strict_types=1);requireRole('subject-officer');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';
$activePage='request-goods';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);$db=database();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $selected=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['aid_request_ids']??[])))));$justification=trim((string)($_POST['justification']??''));
 if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!$selected)$errors[]='Select at least one approved beneficiary need.';if(mb_strlen($justification)<10||mb_strlen($justification)>1000)$errors[]='Provide a justification between 10 and 1000 characters.';
 if(!$errors){try{$db->beginTransaction();$marks=implode(',',array_fill(0,count($selected),'?'));$s=$db->prepare("SELECT ar.id,ar.item_id,ar.quantity,b.ds_division_id FROM aid_requests ar JOIN beneficiaries b ON b.id=ar.beneficiary_id WHERE ar.id IN ($marks) AND ar.status='approved' FOR UPDATE");$s->execute($selected);$needs=$s->fetchAll();if(count($needs)!==count($selected))throw new RuntimeException('One or more selected needs are no longer awaiting goods.');$itemIds=array_unique(array_column($needs,'item_id'));$divisionIds=array_unique(array_column($needs,'ds_division_id'));if(count($itemIds)!==1||count($divisionIds)!==1)throw new RuntimeException('A batch must contain the same item and destination DS Division. Create separate Goods Requests for other items or divisions.');$quantity=array_sum(array_map('intval',array_column($needs,'quantity')));$insert=$db->prepare('INSERT INTO goods_requests(item_id,quantity,destination_ds_division_id,justification,requested_by) VALUES(:item,:quantity,:division,:justification,:user)');$insert->execute(['item'=>$itemIds[0],'quantity'=>$quantity,'division'=>$divisionIds[0],'justification'=>$justification,'user'=>$_SESSION['user_id']]);$goodsId=(int)$db->lastInsertId();$link=$db->prepare('INSERT INTO goods_request_aid_requests(goods_request_id,aid_request_id) VALUES(:goods,:aid)');foreach($selected as $aidId)$link->execute(['goods'=>$goodsId,'aid'=>$aidId]);$update=$db->prepare("UPDATE aid_requests ar JOIN goods_request_aid_requests ga ON ga.aid_request_id=ar.id SET ar.status='goods-requested',ar.goods_request_ref=:goods WHERE ga.goods_request_id=:batch AND ar.status='approved'");$update->execute(['goods'=>$goodsId,'batch'=>$goodsId]);if($update->rowCount()!==count($selected))throw new RuntimeException('The selected needs changed while creating the batch.');$db->commit();logActivity('Goods Requests','Submitted batch Goods Request for '.count($selected).' approved need(s)','GR-'.str_pad((string)$goodsId,4,'0',STR_PAD_LEFT),'pending');$_SESSION['flash_success']='Goods Request created for '.count($selected).' approved beneficiary need(s).';unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=request-goods');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to create Goods Request.';}}
}
try{$needs=$db->query("SELECT ar.id,ar.quantity,ar.prescribed_power,b.full_name,b.nic,b.address,i.item_name,i.variety,d.name district_name,ds.name division_name,b.ds_division_id,ar.item_id FROM aid_requests ar JOIN beneficiaries b ON b.id=ar.beneficiary_id JOIN inventory_items i ON i.id=ar.item_id JOIN districts d ON d.id=b.district_id JOIN ds_divisions ds ON ds.id=b.ds_division_id WHERE ar.status='approved' ORDER BY i.item_name,d.name,ds.name,b.full_name")->fetchAll();$summary=$db->query("SELECT i.id item_id,i.item_name,i.variety,COUNT(*) beneficiaries,SUM(ar.quantity) quantity FROM aid_requests ar JOIN inventory_items i ON i.id=ar.item_id WHERE ar.status='approved' GROUP BY i.id,i.item_name,i.variety ORDER BY quantity DESC,i.item_name")->fetchAll();$s=$db->prepare('SELECT g.*,i.item_name,i.variety,ds.name division_name,u.full_name approver_name,COUNT(ga.aid_request_id) beneficiary_count FROM goods_requests g JOIN inventory_items i ON i.id=g.item_id JOIN ds_divisions ds ON ds.id=g.destination_ds_division_id LEFT JOIN users u ON u.id=g.approved_by LEFT JOIN goods_request_aid_requests ga ON ga.goods_request_id=g.id WHERE g.requested_by=:user GROUP BY g.id ORDER BY g.id DESC');$s->execute(['user'=>$_SESSION['user_id']]);$requests=$s->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$needs=$summary=$requests=[];$errors[]='Goods workflow is unavailable.';}
$labels=['pending-admin-approval'=>'Pending Admin Approval','approved-awaiting-dispatch'=>'Approved — Awaiting Dispatch','dispatched'=>'Dispatched','rejected'=>'Rejected'];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Request Goods from Store | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/subject-officer-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Approved Needs / Request from Store</h1></div></header><main class="dashboard-content goods-workflow-page"><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif;?>
<section class="operation-summary-grid"><?php if(!$summary):?><article class="operation-summary-card"><span>&#128203;</span><p>Approved Needs</p><strong>0</strong><small>Nothing awaiting goods</small></article><?php else:foreach($summary as $s):?><article class="operation-summary-card"><span>&#128230;</span><p><?=htmlspecialchars($s['item_name'].($s['variety']?' — '.$s['variety']:''),ENT_QUOTES,'UTF-8')?> Approved</p><strong><?=(int)$s['quantity']?></strong><small><?=(int)$s['beneficiaries']?> beneficiar<?=((int)$s['beneficiaries']===1?'y':'ies')?> awaiting goods</small></article><?php endforeach;endif;?></section>
<section class="admin-data-card"><div class="admin-data-header"><h2>Create Batch Goods Request</h2><small>Subject Officers can manage approved needs across all districts.</small></div><form method="post" class="goods-request-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><div class="admin-data-table-wrap"><table class="admin-data-table"><thead><tr><th>Select</th><th>Need</th><th>Beneficiary</th><th>NIC</th><th>Item</th><th>Qty</th><th>Destination</th><th>Lens Power</th></tr></thead><tbody><?php if(!$needs):?><tr><td colspan="8" class="admin-empty-row">No Admin-approved needs are awaiting goods.</td></tr><?php else:foreach($needs as $n):?><tr><td><input type="checkbox" name="aid_request_ids[]" value="<?=(int)$n['id']?>"></td><td>AR-<?=str_pad((string)$n['id'],4,'0',STR_PAD_LEFT)?></td><td><?=htmlspecialchars($n['full_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($n['nic'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($n['item_name'].($n['variety']?' — '.$n['variety']:''),ENT_QUOTES,'UTF-8')?></td><td><?=(int)$n['quantity']?></td><td><?=htmlspecialchars($n['district_name'].' / '.$n['division_name'],ENT_QUOTES,'UTF-8')?></td><td><?=$n['prescribed_power']!==null?sprintf('%+.2f',(float)$n['prescribed_power']):'—'?></td></tr><?php endforeach;endif;?></tbody></table></div><label class="goods-full">Batch Justification<textarea name="justification" rows="2" maxlength="1000" required placeholder="Explain why these approved needs are being requested from central store."></textarea></label><button class="admin-primary-action" <?=$needs?'':'disabled'?>>Submit Goods Request</button></form></section>
<section class="admin-data-card goods-list-card"><div class="admin-data-header"><h2>My Goods Requests</h2></div><div class="admin-data-table-wrap"><table class="admin-data-table goods-table"><thead><tr><th>ID</th><th>Item</th><th>Beneficiaries</th><th>Qty</th><th>Destination</th><th>Submitted</th><th>Status</th></tr></thead><tbody><?php if(!$requests):?><tr><td colspan="7" class="admin-empty-row">No goods requests available.</td></tr><?php else:foreach($requests as $r):?><tr><td>GR-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></td><td><?=htmlspecialchars($r['item_name'].($r['variety']?' — '.$r['variety']:''),ENT_QUOTES,'UTF-8')?></td><td><?=(int)$r['beneficiary_count']?></td><td><?=(int)$r['quantity']?></td><td><?=htmlspecialchars($r['division_name'],ENT_QUOTES,'UTF-8')?></td><td><?=date('d M Y',strtotime($r['created_at']))?></td><td><?=htmlspecialchars($labels[$r['status']]??$r['status'],ENT_QUOTES,'UTF-8')?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
